-- ShadowTrace initial schema (SQLite). Invariants are enforced with FKs,
-- unique/check constraints; IDs are opaque UUID hex strings generated by the app.
PRAGMA foreign_keys = ON;

CREATE TABLE organizations (
    id          TEXT PRIMARY KEY,
    name        TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 120),
    created_at  INTEGER NOT NULL
);

CREATE TABLE users (
    id             TEXT PRIMARY KEY,
    org_id         TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    email          TEXT NOT NULL,
    name           TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 120),
    role           TEXT NOT NULL CHECK (role IN ('admin','analyst','viewer')),
    password_hash  TEXT NOT NULL,
    is_active      INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0,1)),
    totp_secret    TEXT,
    created_at     INTEGER NOT NULL,
    last_login_at  INTEGER
);
CREATE UNIQUE INDEX ux_users_email ON users(email);
CREATE INDEX ix_users_org ON users(org_id);

CREATE TABLE sessions (
    id                   TEXT PRIMARY KEY,
    user_id              TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    token_hash           TEXT NOT NULL UNIQUE,
    csrf_token           TEXT NOT NULL,
    created_at           INTEGER NOT NULL,
    last_seen_at         INTEGER NOT NULL,
    idle_expires_at      INTEGER NOT NULL,
    absolute_expires_at  INTEGER NOT NULL,
    revoked_at           INTEGER,
    ip                   TEXT,
    user_agent           TEXT
);
CREATE INDEX ix_sessions_user ON sessions(user_id);

CREATE TABLE invitations (
    id           TEXT PRIMARY KEY,
    org_id       TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    email        TEXT NOT NULL,
    role         TEXT NOT NULL CHECK (role IN ('admin','analyst','viewer')),
    token_hash   TEXT NOT NULL UNIQUE,
    invited_by   TEXT NOT NULL REFERENCES users(id),
    created_at   INTEGER NOT NULL,
    expires_at   INTEGER NOT NULL,
    accepted_at  INTEGER
);

CREATE TABLE targets (
    id                   TEXT PRIMARY KEY,
    org_id               TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    name                 TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 120),
    base_url             TEXT NOT NULL,
    host                 TEXT NOT NULL,
    scheme               TEXT NOT NULL CHECK (scheme IN ('http','https')),
    ports                TEXT NOT NULL,           -- JSON list of ints
    path_prefixes        TEXT NOT NULL,           -- JSON list of strings
    authorization_mode   TEXT NOT NULL CHECK (authorization_mode IN ('ownership','admin','lab_allowlist')),
    authorization_status TEXT NOT NULL CHECK (authorization_status IN ('pending','approved','revoked')),
    attestation          TEXT NOT NULL,
    justification        TEXT,
    verification_token   TEXT NOT NULL,
    verified_at          INTEGER,
    verified_by          TEXT REFERENCES users(id),
    created_by           TEXT NOT NULL REFERENCES users(id),
    created_at           INTEGER NOT NULL,
    limits               TEXT NOT NULL            -- JSON object
);
CREATE UNIQUE INDEX ux_targets_org_host ON targets(org_id, host);
CREATE INDEX ix_targets_org ON targets(org_id);

CREATE TABLE baselines (
    id              TEXT PRIMARY KEY,
    org_id          TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    target_id       TEXT NOT NULL REFERENCES targets(id) ON DELETE CASCADE,
    source          TEXT NOT NULL CHECK (source IN ('url','upload')),
    source_ref      TEXT,
    spec            TEXT NOT NULL,
    endpoint_count  INTEGER NOT NULL DEFAULT 0,
    created_by      TEXT NOT NULL REFERENCES users(id),
    created_at      INTEGER NOT NULL
);
CREATE INDEX ix_baselines_target ON baselines(target_id);

CREATE TABLE scans (
    id                TEXT PRIMARY KEY,
    org_id            TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    target_id         TEXT NOT NULL REFERENCES targets(id) ON DELETE CASCADE,
    created_by        TEXT NOT NULL REFERENCES users(id),
    state             TEXT NOT NULL CHECK (state IN ('queued','running','cancelling','completed','failed','cancelled','timed_out')),
    config            TEXT NOT NULL,               -- JSON scan config
    counters          TEXT NOT NULL DEFAULT '{}',  -- JSON progress counters
    idempotency_key   TEXT NOT NULL,
    baseline_id       TEXT REFERENCES baselines(id),
    worker_id         TEXT,
    heartbeat_at      INTEGER,
    lease_expires_at  INTEGER,
    cancel_requested  INTEGER NOT NULL DEFAULT 0 CHECK (cancel_requested IN (0,1)),
    partial           INTEGER NOT NULL DEFAULT 0 CHECK (partial IN (0,1)),
    error_category    TEXT CHECK (error_category IN ('policy_blocked','target_error','timeout','internal','cancelled')),
    error_message     TEXT,
    created_at        INTEGER NOT NULL,
    started_at        INTEGER,
    finished_at       INTEGER,
    updated_at        INTEGER NOT NULL
);
CREATE UNIQUE INDEX ux_scans_idem ON scans(org_id, idempotency_key);
CREATE INDEX ix_scans_target ON scans(target_id, created_at);
CREATE INDEX ix_scans_state ON scans(state);

CREATE TABLE scan_events (
    id        INTEGER PRIMARY KEY AUTOINCREMENT,
    scan_id   TEXT NOT NULL REFERENCES scans(id) ON DELETE CASCADE,
    ts        INTEGER NOT NULL,
    level     TEXT NOT NULL CHECK (level IN ('debug','info','warning','error')),
    kind      TEXT NOT NULL CHECK (length(kind) <= 40),
    message   TEXT NOT NULL CHECK (length(message) <= 500)
);
CREATE INDEX ix_scan_events_scan ON scan_events(scan_id, id);

CREATE TABLE endpoints (
    id                 TEXT PRIMARY KEY,
    org_id             TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    target_id          TEXT NOT NULL REFERENCES targets(id) ON DELETE CASCADE,
    host               TEXT NOT NULL,
    method             TEXT NOT NULL CHECK (method IN ('GET','HEAD','OPTIONS','POST','PUT','PATCH','DELETE','TRACE')),
    path_template      TEXT NOT NULL,
    query_template     TEXT NOT NULL DEFAULT '',
    classification     TEXT NOT NULL CHECK (classification IN ('shadow','documented','zombie','unknown')),
    validation_status  TEXT NOT NULL CHECK (validation_status IN ('unvalidated','live','redirected','auth_required','not_found','error','blocked','skipped_budget')),
    response_status    INTEGER,
    fingerprint        TEXT NOT NULL,
    first_seen_at      INTEGER NOT NULL,
    last_seen_at       INTEGER NOT NULL,
    first_seen_scan    TEXT REFERENCES scans(id),
    last_seen_scan     TEXT REFERENCES scans(id),
    origin             TEXT NOT NULL
);
CREATE UNIQUE INDEX ux_endpoints_identity ON endpoints(org_id, target_id, method, host, path_template, query_template);
CREATE INDEX ix_endpoints_target ON endpoints(target_id);
CREATE INDEX ix_endpoints_class ON endpoints(target_id, classification);

CREATE TABLE scan_endpoints (
    scan_id            TEXT NOT NULL REFERENCES scans(id) ON DELETE CASCADE,
    endpoint_id        TEXT NOT NULL REFERENCES endpoints(id) ON DELETE CASCADE,
    validation_status  TEXT NOT NULL,
    classification     TEXT NOT NULL,
    PRIMARY KEY (scan_id, endpoint_id)
);

CREATE TABLE endpoint_sources (
    id           INTEGER PRIMARY KEY AUTOINCREMENT,
    endpoint_id  TEXT NOT NULL REFERENCES endpoints(id) ON DELETE CASCADE,
    scan_id      TEXT NOT NULL REFERENCES scans(id) ON DELETE CASCADE,
    source_type  TEXT NOT NULL CHECK (source_type IN ('html','javascript','source_map','openapi','swagger_ui','redoc','postman','docs','robots','sitemap','har','crawler','graphql','manual')),
    source_url   TEXT NOT NULL,
    location     TEXT NOT NULL DEFAULT '',
    method       TEXT NOT NULL DEFAULT 'GET',
    snippet      TEXT NOT NULL DEFAULT '',
    extractor    TEXT NOT NULL,
    created_at   INTEGER NOT NULL
);
CREATE INDEX ix_endpoint_sources_ep ON endpoint_sources(endpoint_id);
CREATE INDEX ix_endpoint_sources_scan ON endpoint_sources(scan_id);

CREATE TABLE observations (
    id              TEXT PRIMARY KEY,
    scan_id         TEXT NOT NULL REFERENCES scans(id) ON DELETE CASCADE,
    endpoint_id     TEXT REFERENCES endpoints(id) ON DELETE CASCADE,
    url             TEXT NOT NULL,
    method          TEXT NOT NULL,
    status_code     INTEGER,
    content_type    TEXT,
    content_length  INTEGER,
    elapsed_ms      INTEGER,
    headers         TEXT NOT NULL DEFAULT '{}',
    snippet         TEXT NOT NULL DEFAULT '',
    error           TEXT,
    checked_at      INTEGER NOT NULL
);
CREATE INDEX ix_observations_scan ON observations(scan_id);
CREATE INDEX ix_observations_ep ON observations(endpoint_id);

CREATE TABLE findings (
    id            TEXT PRIMARY KEY,
    org_id        TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    target_id     TEXT NOT NULL REFERENCES targets(id) ON DELETE CASCADE,
    scan_id       TEXT NOT NULL REFERENCES scans(id) ON DELETE CASCADE,
    endpoint_id   TEXT REFERENCES endpoints(id) ON DELETE SET NULL,
    rule_id       TEXT NOT NULL,
    title         TEXT NOT NULL,
    severity      TEXT NOT NULL CHECK (severity IN ('critical','high','medium','low','info')),
    confidence    TEXT NOT NULL CHECK (confidence IN ('confirmed','high','medium','low')),
    status        TEXT NOT NULL CHECK (status IN ('suspected','confirmed')),
    exposure      REAL NOT NULL CHECK (exposure >= 0 AND exposure <= 1),
    risk_score    REAL NOT NULL CHECK (risk_score >= 0 AND risk_score <= 100),
    fingerprint   TEXT NOT NULL,
    rationale     TEXT NOT NULL,
    limitations   TEXT NOT NULL,
    remediation   TEXT NOT NULL,
    evidence      TEXT NOT NULL,
    created_at    INTEGER NOT NULL
);
CREATE UNIQUE INDEX ux_findings_scan_fp ON findings(scan_id, fingerprint);
CREATE INDEX ix_findings_scan ON findings(scan_id, severity);
CREATE INDEX ix_findings_target ON findings(target_id, fingerprint);

CREATE TABLE triage_records (
    id           TEXT PRIMARY KEY,
    org_id       TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    target_id    TEXT NOT NULL REFERENCES targets(id) ON DELETE CASCADE,
    fingerprint  TEXT NOT NULL,
    status       TEXT NOT NULL CHECK (status IN ('open','accepted_risk','false_positive','fixed')),
    reason       TEXT NOT NULL DEFAULT '',
    updated_by   TEXT REFERENCES users(id),
    updated_at   INTEGER NOT NULL
);
CREATE UNIQUE INDEX ux_triage_fp ON triage_records(target_id, fingerprint);

CREATE TABLE triage_history (
    id         INTEGER PRIMARY KEY AUTOINCREMENT,
    triage_id  TEXT NOT NULL REFERENCES triage_records(id) ON DELETE CASCADE,
    ts         INTEGER NOT NULL,
    status     TEXT NOT NULL,
    reason     TEXT NOT NULL DEFAULT '',
    user_id    TEXT REFERENCES users(id)
);

CREATE TABLE report_exports (
    id          TEXT PRIMARY KEY,
    org_id      TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    scan_id     TEXT NOT NULL REFERENCES scans(id) ON DELETE CASCADE,
    format      TEXT NOT NULL CHECK (format IN ('json','csv_inventory','csv_findings','markdown','html','openapi_stub')),
    created_by  TEXT NOT NULL REFERENCES users(id),
    created_at  INTEGER NOT NULL
);
CREATE INDEX ix_exports_scan ON report_exports(scan_id);

CREATE TABLE audit_log (
    id           INTEGER PRIMARY KEY AUTOINCREMENT,
    org_id       TEXT,
    ts           INTEGER NOT NULL,
    actor_type   TEXT NOT NULL CHECK (actor_type IN ('user','system','worker','anonymous')),
    actor_id     TEXT,
    action       TEXT NOT NULL,
    object_type  TEXT NOT NULL DEFAULT '',
    object_id    TEXT NOT NULL DEFAULT '',
    ip           TEXT NOT NULL DEFAULT '',
    details      TEXT NOT NULL DEFAULT '{}'
);
CREATE INDEX ix_audit_org ON audit_log(org_id, ts);

-- Append-only audit trail: updates and deletes are rejected at the database layer.
CREATE TRIGGER audit_log_no_update BEFORE UPDATE ON audit_log
BEGIN SELECT RAISE(ABORT, 'audit_log is append-only'); END;
CREATE TRIGGER audit_log_no_delete BEFORE DELETE ON audit_log
BEGIN SELECT RAISE(ABORT, 'audit_log is append-only'); END;
